package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/dop251/goja"
)

// CalculateDiscount executes a JavaScript discount rule script in a Goja VM,
// and returns the resulting discount amount.
// Security measures:
// - The order is injected as a single frozen object to avoid prototype pollution and global namespace pollution.
// - A timeout interrupts runaway scripts.
// - A stack size limit prevents deep recursion attacks.
// - The `eval` and `Function` constructors are disabled to harden the sandbox.
// - The result is safely converted to a float64.
func CalculateDiscount(script string, order map[string]interface{}) (float64, error) {
    vm := goja.New()

    // 1. Set a timeout to prevent infinite loops or excessive computation.
    timer := time.AfterFunc(1*time.Second, func() {
        vm.Interrupt("timeout")
    })
    defer timer.Stop()

    // 2. Limit call stack size to avoid stack overflow attacks.
    vm.SetMaxCallStackSize(10000)

    // 3. Disable dangerous built-in globals.
    vm.Set("eval", goja.Undefined())
    vm.Set("Function", goja.Undefined())

    // 4. Safely inject the order as a single frozen object.
    //    JSON serialization ensures that keys like __proto__ become
    //    ordinary own properties and cannot pollute prototypes.
    //    Object.freeze prevents any modification by the script.
    orderJSON, err := json.Marshal(order)
    if err != nil {
        return 0, fmt.Errorf("failed to marshal order: %w", err)
    }
    setupScript := fmt.Sprintf("var order = Object.freeze(JSON.parse(%s));", strconv.Quote(string(orderJSON)))
    _, err = vm.RunString(setupScript)
    if err != nil {
        return 0, fmt.Errorf("failed to set up order: %w", err)
    }

    // 5. Execute the discount calculation script.
    result, err := vm.RunString(script)
    if err != nil {
        // Check for timeout interrupt
        if _, ok := err.(*goja.InterruptedError); ok {
            return 0, fmt.Errorf("script execution timed out")
        }
        return 0, fmt.Errorf("script execution error: %w", err)
    }

    // 6. Convert the result to float64.
    return toFloat64(result)
}

// toFloat64 converts a goja.Value to a float64, handling all common numeric types.
func toFloat64(v goja.Value) (float64, error) {
    exported := v.Export()
    switch val := exported.(type) {
    case float64:
        return val, nil
    case int:
        return float64(val), nil
    case int32:
        return float64(val), nil
    case int64:
        return float64(val), nil
    case float32:
        return float64(val), nil
    case uint:
        return float64(val), nil
    case uint32:
        return float64(val), nil
    case uint64:
        return float64(val), nil
    default:
        return 0, fmt.Errorf("script must return a number, got %T", exported)
    }
}

