	prototypeFreeze := `
		Object.freeze(Object.prototype);
		Object.freeze(Array.prototype);
		Object.freeze(Function.prototype);
		Object.freeze(String.prototype);
		Object.freeze(Number.prototype);
		Object.freeze(Boolean.prototype);
	`
	if _, err := vm.RunString(prototypeFreeze); err != nil {
		return 0.0, fmt.Errorf("failed to initialize VM: %w", err)
	}

	// Put order fields into a single frozen object instead of polluting the global scope.
	orderObj := vm.NewObject()
	for key, value := range order {
		orderObj.Set(key, value)
	}
	vm.Set("order", orderObj)
	if _, err := vm.RunString("Object.freeze(order)"); err != nil {
		return 0.0, fmt.Errorf("failed to freeze order: %w", err)
	}

	// Set a 5‑second timeout to guard against infinite loops or heavy scripts.
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	go func() {
		<-ctx.Done()
		vm.Interrupt("execution timeout")
	}()

	// Execute the user-supplied script.
	result, err := vm.RunString(script)
	if err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return 0.0, fmt.Errorf("script execution timed out after %v", 5*time.Second)
		}
		return 0.0, fmt.Errorf("script execution error: %w", err)
	}

	// Convert the result to float64.
	discount, ok := result.Export().(float64)
	if !ok {
		// Try other numeric types.
		switch v := result.Export().(type) {
		case int:
			discount = float64(v)
		case int32:
			discount = float64(v)
		case int64:
			discount = float64(v)
		case float32:
			discount = float64(v)
		default:
			return 0.0, fmt.Errorf("script must return a number, got %T", result.Export())
		}
	}

	return discount, nil
}

